-- =====================================================================
-- BudBattles update 015: 341 more strains for Strain Match (from strains.csv, Nov 2026)
-- with breeder, genetics, days and the tags fast / long / balcony_ok / small_space.
-- "partner" and "shops_available" are stored for later but never used for ranking or shown.
-- Paste into Supabase → SQL Editor → New query → Run. Run it after 011 (safe to run again).
-- Does not touch battles, entries or votes. The 60 existing strains stay as they are.
-- =====================================================================

do $$
begin
  if to_regclass('public.strains') is null then
    raise exception 'Please run update 011 (011_profile_options_and_strain_match.sql) first, then this one.';
  end if;
end $$;

-- new facts per strain
alter table public.strains
  add column if not exists breeder text,
  add column if not exists genetics text,
  add column if not exists seeds text,
  add column if not exists days int,
  add column if not exists days_meaning text,
  add column if not exists fast boolean not null default false,
  add column if not exists long boolean not null default false,
  add column if not exists balcony_ok boolean not null default false,
  add column if not exists partner boolean not null default false,
  add column if not exists shops_available text[] not null default '{}',
  add column if not exists needs_check boolean not null default false,
  add column if not exists source text;
alter table public.strains
  drop constraint if exists strains_genetics_values, drop constraint if exists strains_days_values,
  drop constraint if exists strains_days_meaning_values, drop constraint if exists strains_has_type;
alter table public.strains
  add constraint strains_genetics_values check (genetics is null or genetics in ('indica', 'indica-dominant', 'hybrid', 'sativa-dominant', 'sativa')),
  add constraint strains_days_values check (days is null or days between 20 and 200),
  add constraint strains_days_meaning_values check (days_meaning is null or days_meaning in ('flowering', 'seed-to-harvest')),
  add constraint strains_has_type check (auto or photo);

-- the new strains have no height / difficulty / flowering weeks (they use days instead)
alter table public.strains alter column type drop not null;
alter table public.strains alter column difficulty drop not null;
alter table public.strains alter column height drop not null;
alter table public.strains alter column flower_min drop not null;
alter table public.strains alter column flower_max drop not null;

-- the same name may exist from different breeders: same name + same breeder = same strain
alter table public.strains drop constraint if exists strains_name_key;
create unique index if not exists strains_name_breeder_key on public.strains (lower(name), coalesce(lower(breeder), ''));

on conflict ((lower(name)), (coalesce(lower(breeder), ''))) do nothing;
